require __DIR__.'/includes/config.php'; lab_sensitive_page('lectura-medidor.php','Lectura del medidor');if(empty($_SESSION['user'])){header('Location:/login.php');exit;}
$uid=(int)$_SESSION['user']['id'];$pdo=db();$success=null;$error=null;
$q=$pdo->prepare('SELECT * FROM cuentas_servicio WHERE usuario_id=? ORDER BY id');$q->execute([$uid]);$services=$q->fetchAll();
$selected=(int)($_GET['cuenta']??($_POST['cuenta_id']??($services[0]['id']??0)));
$serviceCurrent=null;foreach($services as $s){if((int)$s['id']===$selected){$serviceCurrent=$s;break;}}
if($_SERVER['REQUEST_METHOD']==='POST'&&$serviceCurrent){$reading=(float)($_POST['lectura']??0);$obs=trim($_POST['observaciones']??'');$photo=null;if($reading<(float)$serviceCurrent['lectura_actual']){$error='La lectura capturada no puede ser menor a la última lectura registrada.';}elseif($reading>(float)$serviceCurrent['lectura_actual']+400){$error='La lectura presenta una variación atípica. Verifica el valor antes de enviarlo.';}else{
 if(isset($_FILES['foto'])&&$_FILES['foto']['error']!==UPLOAD_ERR_NO_FILE){if($_FILES['foto']['error']!==UPLOAD_ERR_OK||$_FILES['foto']['size']>4*1024*1024){$error='No fue posible adjuntar la fotografía o excede 4 MB.';}else{$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['foto']['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext){$error='La fotografía debe ser JPG, PNG o WEBP.';}else{$dir=__DIR__.'/uploads/lecturas';if(!is_dir($dir))@mkdir($dir,0775,true);$name='lectura-'.$uid.'-'.$serviceCurrent['id'].'-'.date('YmdHis').'.'.$ext;if(@move_uploaded_file($_FILES['foto']['tmp_name'],$dir.'/'.$name))$photo='/uploads/lecturas/'.$name;else $error='No fue posible guardar la fotografía.';}}}
 if(!$error){$st=$pdo->prepare('INSERT INTO lecturas_ciudadanas (usuario_id,cuenta_id,lectura,foto,observaciones,estatus) VALUES (?,?,?,?,?,\'En validación\')');$st->execute([$uid,$serviceCurrent['id'],$reading,$photo,$obs?:null]);$pdo->prepare('INSERT INTO notificaciones (usuario_id,titulo,mensaje,tipo,leida) VALUES (?,?,?,?,0)')->execute([$uid,'Lectura recibida','Recibimos la lectura del medidor '.$serviceCurrent['medidor'].' y será validada.','servicio']);$success='Lectura enviada correctamente. Quedó en validación.';}}
}
$history=[];if($serviceCurrent){$q=$pdo->prepare('SELECT * FROM lecturas_ciudadanas WHERE cuenta_id=? AND usuario_id=? ORDER BY fecha_captura DESC LIMIT 8');$q->execute([$serviceCurrent['id'],$uid]);$history=$q->fetchAll();}
$pageTitle='Lectura del medidor';include __DIR__.'/includes/header.php';
?>
<section class="section account-section"><div class="wrap"><div class="eyebrow">Mi Portal</div><h1>Lectura del medidor</h1><p class="section-intro">Captura tu lectura y, si lo deseas, adjunta una fotografía del medidor para facilitar la validación.</p><div class="meter-layout section-spacer"><div class="meter-form-card"><?php if($success): ?><div class="notice success-notice"><?= htmlspecialchars($success) ?></div><?php endif; ?><?php if($error): ?><div class="notice"><?= htmlspecialchars($error) ?></div><?php endif; ?><?php if(!$services): ?><div class="empty-state"><h2>Primero vincula un servicio</h2><a class="btn" href="/vincular-servicio.php">Vincular servicio</a></div><?php else: ?><form method="get" class="service-selector"><label>Servicio</label><select name="cuenta" onchange="this.form.submit()"><?php foreach($services as $s): ?><option value="<?= $s['id'] ?>" <?= (int)$s['id']===$selected?'selected':'' ?>><?= htmlspecialchars(($s['alias']?:$s['cuenta']).' · '.$s['cuenta']) ?></option><?php endforeach; ?></select></form><?php if($serviceCurrent): ?><div class="meter-current"><div><small>Medidor</small><b><?= htmlspecialchars($serviceCurrent['medidor']) ?></b></div><div><small>Última lectura oficial</small><b><?= number_format((float)$serviceCurrent['lectura_actual'],1) ?></b></div><div><small>Fecha</small><b><?= htmlspecialchars($serviceCurrent['fecha_lectura']) ?></b></div></div><form method="post" enctype="multipart/form-data" class="meter-submit"><input type="hidden" name="cuenta_id" value="<?= $serviceCurrent['id'] ?>"><div class="field"><label>Nueva lectura</label><input type="number" step="0.1" min="<?= htmlspecialchars($serviceCurrent['lectura_actual']) ?>" name="lectura" required placeholder="Ej. <?= number_format((float)$serviceCurrent['lectura_actual']+12,1,'.','') ?>"></div><div class="field"><label>Fotografía del medidor <small>(opcional)</small></label><input type="file" name="foto" accept="image/jpeg,image/png,image/webp"></div><div class="field"><label>Observaciones <small>(opcional)</small></label><textarea name="observaciones" rows="3" placeholder="Ej. medidor sin obstrucciones, lectura visible..."></textarea></div><label class="check-line"><input type="checkbox" required> Confirmo que la lectura corresponde al medidor indicado.</label><button class="btn">Enviar lectura</button></form><?php endif; ?><?php endif; ?></div><aside class="meter-help"><h3>¿Cómo tomar la lectura?</h3><ol><li>Ubica el número de medidor y verifica que coincida con tu cuenta.</li><li>Registra los números completos que aparecen en la carátula.</li><li>No redondees ni estimes el valor.</li><li>Si adjuntas una foto, evita reflejos y procura que los dígitos sean legibles.</li></ol><a href="/cultura-agua.php">Consejos para detectar fugas →</a></aside></div><?php if($history): ?><div class="section-spacer"><div class="section-heading"><div><div class="eyebrow">Historial</div><h2>Lecturas enviadas</h2></div></div><table class="table"><thead><tr><th>Fecha</th><th>Lectura</th><th>Estatus</th><th>Observaciones</th></tr></thead><tbody><?php foreach($history as $h): ?><tr><td><?= htmlspecialchars(substr($h['fecha_captura'],0,16)) ?></td><td><?= number_format((float)$h['lectura'],1) ?></td><td><?= htmlspecialchars($h['estatus']) ?></td><td><?= htmlspecialchars($h['observaciones']?:'—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></section>
